from pysat.formula import CNF
from pysat.solvers import Solver
from pysat.card import CardEnc

n = 15

cnf = CNF()

# Variables: p[i][v] means x[i] == v
p = {}
for i in range(n):
    for v in range(n):
        p[(i, v)] = i * n + v + 1

# Each position i takes exactly one value
for i in range(n):
    # At least one
    cnf.extend(CardEnc.atleast(lits=[p[(i, v)] for v in range(n)], bound=1, encoding=1))
    # At most one - pairwise
    for v1 in range(n):
        for v2 in range(v1+1, n):
            cnf.append([-p[(i, v1)], -p[(i, v2)]])

# For each value v, exactly v positions have that value
for v in range(n):
    lits = [p[(i, v)] for i in range(n)]
    if v == 0:
        # None of them can be true
        for lit in lits:
            cnf.append([-lit])
    else:
        # At least v
        cnf.extend(CardEnc.atleast(lits=lits, bound=v, encoding=1))
        # At most v - pairwise? No, use atmost
        cnf.extend(CardEnc.atmost(lits=lits, bound=v, encoding=1))

solver = Solver(bootstrap_with=cnf)
if solver.solve():
    model = solver.get_model()
    solution = []
    for i in range(n):
        for v in range(n):
            if p[(i, v)] in model:
                solution.append(v)
                break
    print("SATISFIABLE")
    print(solution)
    # Verify
    for i in range(n):
        count = solution.count(i)
        print(f"x[{i}] = {solution[i]}, count of {i} = {count}, match: {solution[i] == count}")
else:
    print("UNSATISFIABLE")
